        if (w[m] ~ /^-[A-Za-z]*r/ || (length(w[m]) > 2 && index("--recursive", w[m]) == 1)) rec = 1
        if (w[m] ~ /^-[A-Za-z]*n/ || w[m] == "--dry-run" || (length(w[m]) > 2 && index("--cached", w[m]) == 1)) keep = 1
      }
