    return
  }
  if (RECURSIVE && XARGS && cmd ~ /^(rm|unlink|shred)$/) deny("deletes every file a list names (xargs " cmd ")")
  if (RECURSIVE && cmd == "rm") for (m = k + 1; m <= n && w[m] != "--"; m++) if (w[m] ~ /^-[A-Za-z]*[rR]/ || (length(w[m]) > 2 && index("--recursive", w[m]) == 1)) deny("deletes recursively")
