      else if (w[m] ~ /^--output=/) output(substr(w[m], 10))
      else if (w[m] ~ /^-[bdfghiMmnRrsuVzcC]*o./) { v = w[m]; sub(/^-[bdfghiMmnRrsuVzcC]*o/, "", v); output(v) }
    }
