}
# cd, pushd and popd move the directory later pieces resolve from. Leaving the
# project is refused. A wildcard is expanded on disk and followed when it names one
# directory; a directory the guard cannot know (a $VARIABLE, $( ), a wildcard that
# names no single directory, a bare name with CDPATH set) refuses what follows it.
function cd_to(w, n, k, cmd,    t, here) {
  for (k++; k <= n && w[k] ~ /^-[LPe@]+$/; k++) ;
  if (k <= n && w[k] == "--") k++
  if (k <= n && w[k] ~ /^[0-9]*[<>]/) k = n + 1
  # popd and a bare pushd go back to a directory this command did not push: unknown.
  if (cmd == "popd") {
    if (k <= n || NSTACK == 0) deny("changes to a directory from the directory stack")
    else { OLD = cwd; cwd = STACK[NSTACK--] }
    return
  }
  if (k > n) {
    if (cmd == "cd") deny("changes to the home directory (cd with no directory)")
    else if (NSTACK == 0) deny("changes to a directory from the directory stack")
    else { t = STACK[NSTACK]; STACK[NSTACK] = cwd; OLD = cwd; cwd = t }
    return
  }
  t = w[k]
  if (t == "-") {
    if (OLD == "") deny("returns to the previous directory, which may be outside the project")
    else { here = cwd; cwd = OLD; OLD = here }
    return
  }
  if (t ~ /^[+-][0-9]+$/) { deny("changes to a directory from the directory stack"); return }
  if (t ~ /^~/) return
  if (t ~ /[$`]/ || (CDPATH_SET && t !~ /^\.?\.?\//)) { LOST = 1; return }
  if (t ~ /[*?[]/) {
    here = cd_glob(cwd, t)
    if (here == "") { LOST = 1; return }
    if (!inside(here)) { deny("changes to a directory outside the project: " t); return }
  }
  else here = absolute(t)
  if (!inside(here)) { deny("changes to a directory outside the project: " t); return }
  if (cmd == "pushd") STACK[++NSTACK] = cwd
  OLD = cwd; cwd = here
}
# One pipeline piece, as the shell words parse() found in it. Quote marks left
# inside a word (text quoted within other quotes) are dropped, so a command quoted
# inside the text of a program is still recognised.
function wrapped(    n, k, w, i, m, part, j, t, cmd) {
  n = 0
  for (i = 1; i <= NW; i++) {
    m = split(WT[i], part, /[ \t\n]+/)
    for (j = 1; j <= m; j++) { t = part[j]; gsub(/^["\047]+|["\047]+$/, "", t); if (t != "") w[++n] = t }
  }
  WRITES = 0
  k = lead(w, n, 1)
  if (!k) return
  if (LOST) deny("runs a command after a cd the guard cannot follow ($VARIABLE, $( ) or a wildcard that names no single directory)")
  refuse(w, n, k)
  cmd = base(w[k])
  if (cmd ~ /^(cd|pushd|popd)$/) cd_to(w, n, k, cmd)
}
# The word a piece runs as its program, past assignments, redirections and simple
# wrappers. Its path is not looked up: a program resolving outside the project (a
# virtual environment python) is not a path the command reads or writes.
function program(    i) {
  for (i = 1; i <= NW; i++) {
    if (WT[i] ~ /^[A-Za-z_][A-Za-z0-9_]*=/) continue
    if (WT[i] ~ /^[0-9]*(<|>|>>|<<|<<-|<<<|<>|>\|)$/) { i++; continue }
    if (base(WT[i]) ~ /^(env|command|builtin|exec|nohup|nice|time|timeout|stdbuf|setsid|xargs|if|then|else|elif|do|while|until|!)$/ || WT[i] ~ /^-/ || WT[i] ~ /^[0-9.]+[smhd]?$/) continue
    return i
  }
  return 0
}
# Shell words. A word joins its unquoted and quoted parts, as the shell does, so
# `.e""nv` is `.env`; WQ and WU count its quoted and unquoted parts, WG marks an
# unquoted wildcard. Redirection operators are words of their own.
function wend() {
  if (WOPEN) { NW++; WT[NW] = WCUR; WQ[NW] = WQN; WU[NW] = WUN; WG[NW] = WGL }
  WCUR = ""; WQN = 0; WUN = 0; WGL = 0; WOPEN = 0
}
function wplain(t) {
  while (t != "") {
    if (match(t, /^[ \t\n]+/)) { wend(); t = substr(t, RLENGTH + 1); continue }
    if (match(t, /^[<>]+\|?/)) {
      if (!(WOPEN && WQN == 0 && WCUR ~ /^[0-9]+$/)) wend()
      WCUR = WCUR substr(t, 1, RLENGTH); WUN++; WOPEN = 1; wend(); t = substr(t, RLENGTH + 1); continue
    }
    match(t, /^[^ \t\n<>]+/)
    if (substr(t, 1, RLENGTH) ~ /[*?[]/) WGL = 1
    WCUR = WCUR substr(t, 1, RLENGTH); WUN++; WOPEN = 1; t = substr(t, RLENGTH + 1)
  }
}
# Splits a piece of a line into unquoted text (PLAIN), quoted text (QUOTED), its
# shape with quote marks dropped and quoted punctuation blanked (SHAPE), where a
# here-document tag can be found, and shell words. The quote state Q carries on, as
# in the shell.
function parse(s,    c, t) {
  PLAIN = ""; QUOTED = ""; SHAPE = ""; NW = 0; WCUR = ""; WUN = 0; WGL = 0
  WQN = (Q != ""); WOPEN = WQN
  while (s != "") {
    if (Q == "") {
      if (match(s, /^[^\\\047"]+/)) { t = substr(s, 1, RLENGTH); s = substr(s, RLENGTH + 1); PLAIN = PLAIN t; SHAPE = SHAPE t; wplain(t); continue }
      c = substr(s, 1, 1)
      if (c == "\\") { t = substr(s, 2, 1); s = substr(s, 3); PLAIN = PLAIN t; SHAPE = SHAPE t; WCUR = WCUR t; WUN++; WOPEN = 1; continue }
      Q = c; PLAIN = PLAIN " "; s = substr(s, 2); WQN++; WOPEN = 1; continue
    }
    if ((Q == "\047" && match(s, /^[^\047]+/)) || (Q == "\"" && match(s, /^[^"\\]+/))) {
      t = substr(s, 1, RLENGTH); s = substr(s, RLENGTH + 1); QUOTED = QUOTED t; WCUR = WCUR t
      gsub(/[^A-Za-z0-9_.-]/, "_", t); SHAPE = SHAPE t; continue
    }
    c = substr(s, 1, 1)
    if (c == "\\") { t = substr(s, 2, 1); s = substr(s, 3); QUOTED = QUOTED t; WCUR = WCUR t; gsub(/[^A-Za-z0-9_.-]/, "_", t); SHAPE = SHAPE t; continue }
    Q = ""; QUOTED = QUOTED " "; s = substr(s, 2)
  }
  wend()
}
# A line, piece by piece. A ( ) group or $( ) keeps its cd to itself. Each word that
# could be a path is looked up on disk from the directory the piece runs in, as a
# write when the command of the piece writes or the word follows > or >>.
function check_line(l,    rest, seg, sep, shape, i, t, j, here, p, prog, v) {
  if (l ~ /\$\{?HOME([^A-Za-z0-9_]|$)/) deny("names the home directory")
  gsub(/&>/, " >", l); gsub(/>&/, "> ", l); gsub(/<&/, "< ", l)
  shape = ""; rest = l
  while (rest != "") {
    if (match(rest, /[;&|(){}`]+/)) { seg = substr(rest, 1, RSTART - 1); sep = substr(rest, RSTART, RLENGTH); rest = substr(rest, RSTART + RLENGTH) }
    else { seg = rest; sep = ""; rest = "" }
    parse(seg)
    check_words(PLAIN, 0); check_words(QUOTED, 1)
    shape = shape " " SHAPE
    here = cwd; prog = program()
    wrapped()
    for (i = 1; i <= NW; i++) {
      t = WT[i]
      if (WQ[i] && WQ[i] + WU[i] > 1) check_words(t, 0)
      p = (WRITES || (i > 1 && WT[i - 1] ~ /^[0-9]*(>|>>|>\||<>)$/)) ? "w" : "r"
      # A path attached to an option (-t.claude, --target-directory=.claude, of=) too.
      if (p == "w" && t != "" && t !~ /[$`]/) {
        v = t
        if (v ~ /^(-[-A-Za-z0-9]*|of)=/) sub(/^[^=]*=/, "", v)
        else if (v ~ /^-[A-Za-z0-9]+[.\/]/) sub(/^-[A-Za-z0-9]+/, "", v)
        if (v != "" && v !~ /^[-~]/ && protected(from(here, v), 1)) guarded(t)
      }
      if (i == prog || LOST || t == "" || t ~ /^[-~]/ || t ~ /[$`=<>\\ \t\n]/ || (t ~ /^\// && !under(normal(t), dir) && !scratch(normal(t)))) continue
      query(WG[i] ? "g" : "l", p, here, t)
    }
    for (j = 1; j <= length(sep); j++) {
      if (substr(sep, j, 1) == "(") PARENS[++NPARENS] = cwd
      else if (substr(sep, j, 1) == ")" && NPARENS > 0) cwd = PARENS[NPARENS--]
    }
  }
  return shape
}
# Here-document bodies are data and are skipped, unless a shell reads them.
function check_command(cmd,    nl, line, k, rest, shape, tag, ntag, body, tags, strip, shell) {
  if (cmd ~ /(^|[^A-Za-z0-9_])CDPATH=/) deny("sets CDPATH, which changes where cd goes")
  if (cmd ~ /(^|[^A-Za-z0-9_.-])[gmn]?awk[ \t]/ && cmd ~ /system[ \t]*\(|\|[ \t]*getline|\|&|print[^;}]*\|[ \t]*"/) deny("runs a shell command from an awk program")
  embedded(cmd)
  nl = split(cmd, line, "\n"); ntag = 0; body = 0; Q = ""
  for (k = 1; k <= nl; k++) {
    if (body) {
      rest = line[k]; if (strip[body]) sub(/^\t+/, "", rest)
      if (rest == tags[body]) { body = (body < ntag) ? body + 1 : 0; if (!body) ntag = 0; continue }
      if (shell[body]) check_line(line[k])
      continue
    }
    shape = check_line(line[k])
    gsub(/<<</, " ", shape)
    while (match(shape, /<<-?[ \t]*[A-Za-z0-9_.-]+/)) {
      tag = substr(shape, RSTART, RLENGTH); shape = substr(shape, RSTART + RLENGTH)
      ntag++; strip[ntag] = (substr(tag, 3, 1) == "-")
      shell[ntag] = (line[k] ~ /(^|[ \t;&|(])(sh|bash|zsh|dash|ksh)([ \t;&|)]|$)/)
      sub(/^<<-?[ \t]*/, "", tag); tags[ntag] = tag
    }
    if (ntag) body = 1
  }
}
BEGIN {
  READ_NAME = "^([.]env|[.]env[.][^/]*|[^/]*[.]env|[.]envrc|[.]netrc|[.]npmrc|[.]pypirc|[.]dockercfg|[.]git-credentials|[.]htpasswd|token[.]json|auth[.]json|credentials[.]json|secrets[.]json|secrets[.]yml|secrets[.]yaml|[^/]*credentials[^/]*[.]json|service-account[^/]*[.]json|service_account[^/]*[.]json|id_rsa[^/]*|id_dsa[^/]*|id_ecdsa[^/]*|id_ed25519[^/]*|[^/]*[.]pem|[^/]*[.]key|[^/]*[.]p12|[^/]*[.]pfx|[^/]*[.]jks|[^/]*[.]keystore|[^/]*[.]kdbx|[^/]*[.]tfvars|[^/]*[.]tfstate|[^/]*[.]tfstate[.][^/]*|[^/]*[.]ovpn|[^/]*[.]gpg|[.]ssh|[.]aws|[.]gnupg|[.]azure|[.]kube|[.]secrets|secrets|private_keys)$"
  READ_PATH = ""
  EDIT_NAME = "^([.]env|[.]env[.][^/]*|[^/]*[.]env|[.]envrc|[.]netrc|[.]npmrc|[.]pypirc|[.]dockercfg|[.]git-credentials|[.]htpasswd|token[.]json|auth[.]json|credentials[.]json|secrets[.]json|secrets[.]yml|secrets[.]yaml|[^/]*credentials[^/]*[.]json|service-account[^/]*[.]json|service_account[^/]*[.]json|id_rsa[^/]*|id_dsa[^/]*|id_ecdsa[^/]*|id_ed25519[^/]*|[^/]*[.]pem|[^/]*[.]key|[^/]*[.]p12|[^/]*[.]pfx|[^/]*[.]jks|[^/]*[.]keystore|[^/]*[.]kdbx|[^/]*[.]tfvars|[^/]*[.]tfstate|[^/]*[.]tfstate[.][^/]*|[^/]*[.]ovpn|[^/]*[.]gpg|[.]ssh|[.]aws|[.]gnupg|[.]azure|[.]kube|[.]secrets|secrets|private_keys)$"
  EDIT_PATH = ""
  ANY_NAME = "^([.]env|[.]env[.][^/]*|[^/]*[.]env|[.]envrc|[.]netrc|[.]npmrc|[.]pypirc|[.]dockercfg|[.]git-credentials|[.]htpasswd|token[.]json|auth[.]json|credentials[.]json|secrets[.]json|secrets[.]yml|secrets[.]yaml|[^/]*credentials[^/]*[.]json|service-account[^/]*[.]json|service_account[^/]*[.]json|id_rsa[^/]*|id_dsa[^/]*|id_ecdsa[^/]*|id_ed25519[^/]*|[^/]*[.]pem|[^/]*[.]key|[^/]*[.]p12|[^/]*[.]pfx|[^/]*[.]jks|[^/]*[.]keystore|[^/]*[.]kdbx|[^/]*[.]tfvars|[^/]*[.]tfstate|[^/]*[.]tfstate[.][^/]*|[^/]*[.]ovpn|[^/]*[.]gpg|[.]ssh|[.]aws|[.]gnupg|[.]azure|[.]kube|[.]secrets|secrets|private_keys)$"
  ANY_PATH = ""
  DENY = "^(rm -r|rm -R|rm -rf|rm -fr|rm -Rf|rm -fR|rm --recursive|sudo|su|doas|dd|mkfs|shred|chmod -R|chown -R|curl|wget|ssh|scp|sftp|nc|ncat|netcat|telnet|ftp|rsync|socat|gh|git push|git fetch|git pull|git clone|git reset --hard|git clean|git checkout --|git restore|git rebase|git branch -D|git stash drop|git stash clear|git tag -d|git filter-branch|git update-ref|npm publish|pnpm publish|yarn publish|yarn npm publish|bun publish|uv publish|twine upload|poetry publish|flit publish|hatch publish|pdm publish|cargo publish|gem push|mix hex[.]publish|cat [.]env|head [.]env|tail [.]env)( |$)"
  PROJECT = "^(uv build)( |$)|^(uv sync)$"
  RECURSIVE = "1"
  HELPER = "P=$1\nshift\nunset CDPATH\nnl=\047\n\047\nIFS=$nl\nset -f\nr=$(realpath -- \"$P\" 2>/dev/null) && printf \047D %s\\n\047 \"$r\"\nL=\nW=\nt=0\nwhile [ $# -ge 4 ]; do\n  m=$1 p=$2 c=$3 w=$4\n  shift 4\n  cd -- \"$c\" 2>/dev/null || continue\n  case $m in\n  n)\n    case $(PATH=${OLIVIUM_PATH:-$PATH}; command -v \"$w\" 2>/dev/null) in /*) continue ;; esac\n    x=$c\n    while :; do\n      if [ -e \"$x/node_modules/.bin/$w\" ] || [ -e \"$x/node_modules/$w/package.json\" ]; then continue 2; fi\n      case $x in \"$P\" | / | \047\047) break ;; esac\n      x=${x%/*}\n    done\n    f=$P/package.json\n    if [ -f \"$f\" ] && [ ! -L \"$f\" ] && [ $(($(wc -c <\"$f\"))) -le 1048576 ] &&\n      OLIVIUM_BIN=$w awk \047{ s = s $0 \"\\n\" }\nEND {\n  p = ENVIRON[\"OLIVIUM_BIN\"]; n = length(s); i = 1; d = 0; m = 0\n  while (i <= n) {\n    if (match(substr(s, i, 4096), /^[^][\"{},:]+/)) { i += RLENGTH; continue }\n    c = substr(s, i, 1)\n    if (c == \"\\\"\") {\n      st = ++i\n      while (i <= n) {\n        if (match(substr(s, i, 4096), /^[^\"\\\\]+/)) { i += RLENGTH; continue }\n        if (substr(s, i, 1) == \"\\\\\") { i += 2; continue }\n        break\n      }\n      if (d <= 2) { m++; T[m] = \"s\"; V[m] = substr(s, st, i - st); D[m] = d }\n      i++; continue\n    }\n    if (c == \"{\" || c == \"[\") { if (d <= 2) { m++; T[m] = c; D[m] = d } d++ }\n    else if (c == \"}\" || c == \"]\") { d--; if (d <= 2) { m++; T[m] = c; D[m] = d } }\n    else if (d <= 2) { m++; T[m] = c; D[m] = d }\n    i++\n  }\n  for (k = 1; k <= m; k++) {\n    if (T[k] != \"s\" || D[k] != 1 || T[k + 1] != \":\") continue\n    if (V[k] == \"name\" && T[k + 2] == \"s\") name = V[k + 2]\n    if (V[k] != \"bin\") continue\n    if (T[k + 2] == \"s\") sbin = 1\n    else if (T[k + 2] == \"{\")\n      for (j = k + 3; j <= m && !(T[j] == \"}\" && D[j] == 1); j++)\n        if (T[j] == \"s\" && D[j] == 2 && T[j + 1] == \":\" && V[j] == p) obin = 1\n  }\n  exit !(p != \"\" && (obin || (sbin && name == p)))\n}\n\047 \"$f\" 2>/dev/null; then continue; fi\n    printf \047N %s\\n\047 \"$w\"\n    ;;\n  c)\n    set +f\n    k=0\n    for f in $w; do\n      if [ -d \"$f\" ]; then k=$((k + 1)); x=$f; fi\n    done\n    set -f\n    if [ \"$k\" -eq 1 ] && x=$(cd -- \"$x\" 2>/dev/null && pwd -P); then printf \047C %s\\n\047 \"$x\"; fi\n    ;;\n  g)\n    set +f\n    for f in $w; do\n      [ -e \"$f\" ] || [ -L \"$f\" ] || continue\n      t=$((t + 1))\n      [ \"$t\" -gt 2000 ] && break\n      case $f in /*) ;; *) f=$PWD/$f ;; esac\n      printf \047G%s %s\\n\047 \"$p\" \"$f\"\n      if [ \"$p\" = w ]; then W=$W$f$nl; else L=$L$f$nl; fi\n    done\n    set -f\n    ;;\n  *)\n    case $w in /*) f=$w ;; *) f=$PWD/$w ;; esac\n    while [ -n \"$f\" ] && [ ! -e \"$f\" ] && [ ! -L \"$f\" ]; do f=${f%/*}; done\n    [ -n \"$f\" ] || continue\n    if [ \"$p\" = w ]; then W=$W$f$nl; else L=$L$f$nl; fi\n    ;;\n  esac\ndone\necho R\n[ -n \"$L\" ] && realpath -- $L 2>/dev/null\necho W\n[ -n \"$W\" ] && realpath -- $W 2>/dev/null\nexit 0\n"
  SYSTEM = "^(bin|boot|dev|etc|home|lib|lib32|lib64|libx32|media|mnt|opt|proc|root|run|sbin|snap|srv|sys|tmp|usr|var|nix|private|Users|Library|System|Applications|Volumes|cores)$"
  WRAPPER = "^(env|command|builtin|exec|eval|nohup|nice|ionice|time|timeout|xargs|stdbuf|setsid|sudo|doas|npx|bunx|uvx|sh|bash|zsh|dash|ksh|if|then|else|elif|do|while|until|!)$"
  RUNNER = "^(uv|poetry|pdm|hatch|pipenv|pipx|npm|pnpm|yarn|bun)$"
  WRITER = "^(rm|rmdir|unlink|mv|cp|ln|install|shred|truncate|tee|touch|chmod|chown|chgrp|dd|rsync)$"
  OPTARG["timeout"] = "^(-s|-k|--signal|--kill-after)$"
  OPTARG["nice"] = "^(-n|--adjustment)$"
  OPTARG["ionice"] = "^(-c|-n|-p|-P|-u|--class|--classdata|--pid|--pgid|--uid)$"
  OPTARG["xargs"] = "^(-I|-L|-n|-P|-s|-d|-E|-a|--arg-file|--delimiter|--max-args|--max-lines|--max-procs|--max-chars|--eof|--process-slot-var)$"
  OPTARG["env"] = "^(-u|-C|--unset|--chdir)$"
  OPTARG["exec"] = "^-a$"
  OPTARG["time"] = "^(-f|-o|--format|--output)$"
  OPTARG["stdbuf"] = "^(-i|-o|-e|--input|--output|--error)$"
  OPTARG["sh"] = OPTARG["bash"] = OPTARG["zsh"] = OPTARG["dash"] = OPTARG["ksh"] = "^(-o|-O|--rcfile|--init-file)$"
  OPTARG["npx"] = OPTARG["bunx"] = OPTARG["npm exec"] = OPTARG["npm x"] = OPTARG["bun x"] = "^(-p|--package|-w|--workspace|--prefix|--registry|--cache|--userconfig)$"
  OPTARG["uvx"] = "^(--from|--with|-w|--python|-p|--index|--index-url|--extra-index-url)$"
  OPTARG["uv run"] = "^(--with|-w|--with-editable|--with-requirements|--python|-p|--package|--extra|--group|--only-group|--no-group|--env-file|--directory|--project|--index|--index-url|--default-index|--extra-index-url|--find-links|-f|--config-file|--cache-dir)$"
  OPTARG["pnpm exec"] = "^(-C|--dir|--filter|-F|--workspace-concurrency)$"
  OPTARG["pip"] = "^(-r|-c|-t|-i|-f|-d|--requirement|--constraint|--target|--dest|--index-url|--extra-index-url|--find-links|--prefix|--root|--src|--python|--python-version|--platform|--implementation|--abi|--only-binary|--no-binary|--progress-bar|--log|--cache-dir|--report|-C|--config-settings|--group|--upgrade-strategy|--trusted-host|--proxy|--cert|--client-cert|--retries|--timeout|--exists-action|--root-user-action|--optional|--dev-group|--extra|-w|--wheel-dir)$"
  OPTARG["npm"] = "^(-w|--workspace|--prefix|--registry|--cache|--tag|--omit|--include|--install-strategy|--userconfig|--filter|-F|-C|--dir)$"
