{ input = input $0 " " }
END {
  cwd = field(input, "cwd")
  if (dir == "") dir = cwd
  if (dir ~ /^\//) dir = normal(dir)
  cwd = cwd ~ /^\// ? normal(cwd) : dir
  dirtop = dir; sub(/^\/+/, "", dirtop); sub(/\/.*/, "", dirtop)
  transcripts = field(input, "transcript_path"); sub(/\/[^\/]*$/, "", transcripts)
  if (transcripts !~ /^\/./) transcripts = ""
  CDPATH_SET = (ENVIRON["CDPATH"] != "")
  tool = field(input, "tool_name")
  if (tool == "Bash") {
    check_command(field(input, "command"))
    if (reason == "" && NQ) {
      probe()
      for (k = 1; k <= NFOUND; k++) {
        v = FV[k]
        if (FK[k] == "N") fetching("would download", v, "")
        else if (inside(v)) {
          if (secret(rel(v), ANY_NAME, ANY_PATH)) deny("reaches a secret file through a link or wildcard: " rel(v))
          else if (FP[k] == "w" && protected(v, FK[k] == "G")) guarded(rel(v))
        }
        else if (secret(v, ANY_NAME, ANY_PATH)) deny("reaches a secret file through a link or wildcard: " v)
        else if (!device(v) && !under(v, transcripts) && !scratch(v)) deny((FP[k] == "w" ? "writes" : "reaches") " a path outside the project through a link: " v)
      }
    }
  }
  else if (tool ~ /^(Read|Grep|Glob)$/) {
    path = field(input, "file_path"); if (path == "") path = field(input, "path")
    if (secret(rel(path), READ_NAME, READ_PATH)) deny("names a secret file: " path)
    else if (path != "" && (path ~ /^~/ || !(under(absolute(path), dir) || under(absolute(path), transcripts) || device(absolute(path)) || scratch(absolute(path))))) deny("reads outside the project: " path)
    else if (path != "" && (under(absolute(path), dir) || scratch(absolute(path)))) linked(path, READ_NAME, READ_PATH, "reads", 0)
  }
  else if (tool ~ /^(Edit|Write|MultiEdit|NotebookEdit)$/) {
    path = field(input, "file_path"); if (path == "") path = field(input, "notebook_path")
    if (secret(rel(path), EDIT_NAME, EDIT_PATH)) deny("names a secret file: " path)
    else if (path != "" && (path ~ /^~/ || !(under(absolute(path), dir) || scratch(absolute(path))))) deny("writes outside the project: " path)
    else if (path != "" && protected(absolute(path), 1)) guarded(path)
    else if (path != "") linked(path, EDIT_NAME, EDIT_PATH, "writes", 1)
  }
  if (reason == "") exit 0
  reason = substr(reason, 1, 200)
  gsub(/[^ -~]/, "?", reason); gsub(/["\\]/, "?", reason)
  # The second sentence ends the detour: a missing tool or a path outside the project
  # is not there to be found, so the agent continues without it. Every refusal stays.
  if (FETCH) tail = (TOOL != "" ? TOOL : "It") " is not installed here; continue without it. Do not install or download tools."
  else if (reason ~ /outside the project|home directory/) tail = "What is outside the project is not available here; continue without it, and put scratch files in /tmp."
  else tail = "Keep work inside the project, put scratch files in /tmp, and leave secrets, the network, the package registry, git history and .claude alone."
  printf "{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"deny\",\"permissionDecisionReason\":\"Olivium guard: this call %s. %s\"}}\n", reason, tail
}'
